import pandas as pd


def run(inputs: dict) -> dict:
    invoices = inputs["invoices"].copy()
    payments = inputs["payments"].copy()

    # Track remaining open amount per invoice
    open_amount = {}
    orig_amount = {}
    for row in invoices.itertuples(index=False):
        open_amount[row.invoice_id] = float(row.amount)
        orig_amount[row.invoice_id] = float(row.amount)

    # Build per-customer invoice order: due_date, then invoice_id
    inv_by_cust = {}
    if len(invoices) > 0:
        for cust, grp in invoices.groupby("customer_id"):
            grp_sorted = grp.sort_values(["due_date", "invoice_id"])
            inv_by_cust[cust] = list(grp_sorted["invoice_id"])

    # Payments processed per customer, ordered by paid_ts then payment_id
    payments_sorted = payments.sort_values(["customer_id", "paid_ts", "payment_id"])

    allocations = []
    credit = {}

    for row in payments_sorted.itertuples(index=False):
        cust = row.customer_id
        pay_id = row.payment_id
        left = float(row.amount)

        invs = inv_by_cust.get(cust, [])
        for inv_id in invs:
            if left <= 0:
                break
            oa = open_amount.get(inv_id, 0.0)
            if oa <= 0:
                continue
            pay = left if left < oa else oa
            open_amount[inv_id] = oa - pay
            left -= pay
            allocations.append((pay_id, inv_id, pay))
            if left == 0:
                break

        if left > 0:
            credit[cust] = credit.get(cust, 0.0) + left

    # Build invoice_status
    status_rows = []
    for row in invoices.itertuples(index=False):
        inv_id = row.invoice_id
        oa = open_amount.get(inv_id, 0.0)
        orig = orig_amount.get(inv_id, 0.0)

        if abs(oa - orig) < 1e-9:
            status = "OPEN"
        elif abs(oa) < 1e-9:
            status = "PAID"
        else:
            status = "PARTIAL"

        status_rows.append((inv_id, oa, status))

    invoice_status = pd.DataFrame(
        status_rows, columns=["invoice_id", "open_amount", "status"]
    )
    if len(invoice_status) > 0:
        invoice_status["invoice_id"] = invoice_status["invoice_id"].astype("int64")
        invoice_status["open_amount"] = invoice_status["open_amount"].astype("float64")

    allocations_df = pd.DataFrame(
        allocations, columns=["payment_id", "invoice_id", "applied_amount"]
    )
    if len(allocations_df) > 0:
        allocations_df["payment_id"] = allocations_df["payment_id"].astype("int64")
        allocations_df["invoice_id"] = allocations_df["invoice_id"].astype("int64")
        allocations_df["applied_amount"] = allocations_df["applied_amount"].astype(
            "float64"
        )
    else:
        allocations_df = pd.DataFrame(
            columns=["payment_id", "invoice_id", "applied_amount"]
        )
        allocations_df["payment_id"] = allocations_df["payment_id"].astype("int64")
        allocations_df["invoice_id"] = allocations_df["invoice_id"].astype("int64")
        allocations_df["applied_amount"] = allocations_df["applied_amount"].astype(
            "float64"
        )

    credit_rows = [(c, amt) for c, amt in credit.items() if amt > 0]
    customer_credit = pd.DataFrame(
        credit_rows, columns=["customer_id", "unapplied_amount"]
    )
    if len(customer_credit) > 0:
        customer_credit["customer_id"] = customer_credit["customer_id"].astype("int64")
        customer_credit["unapplied_amount"] = customer_credit[
            "unapplied_amount"
        ].astype("float64")
    else:
        customer_credit = pd.DataFrame(
            columns=["customer_id", "unapplied_amount"]
        )
        customer_credit["customer_id"] = customer_credit["customer_id"].astype("int64")
        customer_credit["unapplied_amount"] = customer_credit[
            "unapplied_amount"
        ].astype("float64")

    return {
        "invoice_status": invoice_status,
        "allocations": allocations_df,
        "customer_credit": customer_credit,
    }
